@pytest.mark.parametrize(
    "schema",
    [
        param(
            None,
            id="implicit_schema",
            marks=[
                pytest.mark.notimpl(["druid"]),
                pytest.mark.notyet(["polars"], raises=PolarsComputeError),
            ],
        ),
        param({"s": "string", "new_col": "double"}, id="explicit_schema"),
