                rows.append(first_row.format(**locals()))
                for inv_file, inv_sig in t_inv[1:]:
                    rows.append(other_row.format(**locals()))
            else:
                rows.append(noinv_row.format(**locals()))

        return table.format(rows='\n'.join(rows))


