class FlaskPluginLoader(Loader):
    def handle_error(self, exception, cause):
        current_app.logger.exception(
            "%s; original traceback follows", exception, exc_info=cause or exception
        )


def create_app(config):
    app = Flask(__name__)
    app.secret_key = 'secret'

    app.config['READER_CONFIG'] = config
    app.teardown_appcontext(close_db)

    # Force reader plugins to load, so we can fail fast for import errors
    # (although some errors may just be logged while we use FlaskPluginLoader).
    with app.app_context():
        get_reader()

    app.register_blueprint(blueprint)

    # NOTE: this is part of the app extension API
    app.reader_additional_enclosure_links = []

    # app_context() needed for logging to work.
    with app.app_context():
        FlaskPluginLoader(config.merged('app').get('plugins', {})).load_plugins(app)

    return app

import difflib
import os
import signal
import shutil
import sys

import vagrant
import click
from click.exceptions import ClickException

from popper import __version__ as popper_version, log as log


class Context(object):
    pass


log = log.setup_logging()
pass_context = click.make_pass_decorator(Context, ensure=True)
cmd_folder = os.path.abspath(os.path.join(os.path.dirname(__file__),
                                          'commands'))
popper_version = popper_version


class PopperCLI(click.MultiCommand):

    def list_commands(self, ctx):
        rv = []
        for filename in os.listdir(cmd_folder):
            if filename.endswith('.py') and filename.startswith('cmd_'):
                rv.append(filename[4:-3])
        rv.sort()
        return rv

    def get_command(self, ctx, name):
        try:
            if sys.version_info[0] == 2:
                name = name.encode('ascii', 'replace')
            mod = __import__('popper.commands.cmd_' + name,
                             None, None, ['cli'])
        except ImportError as e:
            commands = self.list_commands(ctx)
            most_similar_commands = ", ".join(
                difflib.get_close_matches(
                    name, commands, 3, 0.3))
            message = ""
            if len(most_similar_commands) != 0:
                message = "\n\nThe most similar commands are: " \
                    + most_similar_commands
            raise ClickException(
                "Command '" + name + "' doesn't exist. " +
                "\nType 'popper --help' for more."
                + message + '\n' + str(e)
            )
        return mod.cli


@click.command(cls=PopperCLI)
@pass_context
def cli(ctx):
    """Popper command line interface."""
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGUSR1, signal_handler)


docker_list = list()
vagrant_list = list()
process_list = list()
interrupt_params = dict()
flist = None


def signal_handler(sig, frame):

    if interrupt_params.get('parallel', None) and flist:
        for future in flist:
            future.cancel()

    for pid in process_list:
        log.info("Stopping process '{}'".format(pid))
        try:
            os.killpg(os.getpgid(pid), signal.SIGTERM)
        except OSError:
            pass

    for container in docker_list:
        log.info("Stopping container '{}'".format(container.name))
        container.stop(timeout=1)

    for box_path in vagrant_list:
        log.info("Stopping box '{}'".format(box_path))
        vagrant.Vagrant(root=box_path).halt()

    sys.exit(0)

