    Database, SkipIfNotInstalledDecorator, get_unused_port
)

__all__ = ['Cassandra', 'skipIfNotInstalled', 'skipIfNotFound']

SEARCH_PATHS = ['/usr/local/cassandra',
                '/usr/local/apache-cassandra',
                '/usr/local/opt/cassandra']


class Cassandra(Database):
    BOOT_TIMEOUT = 20
    DEFAULT_SETTINGS = dict(auto_start=2,
                            base_dir=None,
                            cassandra_home=None,
                            pid=None,
                            copy_data_from=None)
    subdirectories = ['conf', 'commitlog', 'data', 'saved_caches', 'tmp']

    def initialize(self, **kwargs):
        self.cassandra_home = self.settings.get('cassandra_home')
        if self.cassandra_home is None:
            self.cassandra_home = find_cassandra_home()

        self.cassandra_bin = self.settings.get('cassandra_bin')
        if self.cassandra_bin is None:
            self.cassandra_bin = os.path.join(self.cassandra_home, 'bin', 'cassandra')

        with open(os.path.join(self.cassandra_confdir, 'cassandra.yaml')) as fd:
            self.cassandra_yaml = yaml.load(fd.read())
            self.cassandra_yaml['commitlog_directory'] = os.path.join(self.base_dir, 'commitlog')
            self.cassandra_yaml['data_file_directories'] = [os.path.join(self.base_dir, 'data')]
            self.cassandra_yaml['saved_caches_directory'] = os.path.join(self.base_dir, 'saved_caches')

            cassandra_version = strip_version(self.cassandra_home)
            if cassandra_version is None or cassandra_version > (1, 2):
                self.cassandra_yaml['start_rpc'] = True

            for key, value in self.settings.get('cassandra_yaml', {}):
                self.settings['cassandra_yaml'][key] = value

        if self.settings['auto_start']:
            if os.path.exists(self.pid_file):
                raise RuntimeError('cassandra is already running (%s)' % self.pid_file)

    @property
    def pid_file(self):
        return os.path.join(self.base_dir, 'tmp', 'cassandra.pid')

    @property
    def cassandra_confdir(self):
        path = os.path.join(self.cassandra_home, 'conf')
        if os.path.exists(path):
            return path
        elif os.path.exists('/usr/local/etc/cassandra'):  # Homebrew
            return '/usr/local/etc/cassandra'
        else:
            raise RuntimeError("could not find confdir of cassandra")

    def server_list(self):
        hostname = '127.0.0.1:%d' % self.cassandra_yaml['rpc_port']
        return [hostname]

    def get_data_directory(self):
        return os.path.join(self.base_dir, 'data')

    def initialize_database(self):
        # conf directory
        conf_dir = os.path.join(self.base_dir, 'conf')
        for filename in os.listdir(self.cassandra_confdir):
            srcpath = os.path.join(self.cassandra_confdir, filename)
            destpath = os.path.join(conf_dir, filename)
            if not os.path.exists(destpath):
                if filename == 'log4j-server.properties':
                    logpath = os.path.join(self.base_dir, 'tmp', 'system.log')
                    with open(srcpath) as src:
                        with open(destpath, 'w') as dest:
                            property = re.sub('log4j.appender.R.File=.*',
                                              'log4j.appender.R.File=%s' % logpath,
                                              src.read())
                            dest.write(property)
                elif os.path.isdir(srcpath):
                    copytree(srcpath, destpath)
                else:
                    copyfile(srcpath, destpath)

    def get_server_commandline(self):
        return [self.cassandra_bin, '-f']

    def is_server_available(self):
        try:
            sock = socket.create_connection(('127.0.0.1', self.cassandra_yaml['rpc_port']), 1.0)
            sock.shutdown(socket.SHUT_RDWR)
            sock.close()
            return True
        except:
            return False

    def prestart(self):
        os.environ['CASSANDRA_CONF'] = os.path.join(self.base_dir, 'conf')

        # assign ports to cassandra
        config_keys = ['rpc_port', 'storage_port', 'ssl_storage_port', 'native_transport_port']
        for key in config_keys:
            if key in self.cassandra_yaml:
                self.cassandra_yaml[key] = get_unused_port()

        # replace cassandra-env.sh
        with open(os.path.join(self.base_dir, 'conf', 'cassandra-env.sh'), 'r+t') as fd:
            script = re.sub('JMX_PORT="7199"', 'JMX_PORT="%d"' % get_unused_port(), fd.read())
            fd.seek(0)
            fd.write(script)

        # generate cassandra.yaml
        with open(os.path.join(self.base_dir, 'conf', 'cassandra.yaml'), 'wt') as fd:
            fd.write(yaml.dump(self.cassandra_yaml))

    def poststart(self):
        # create test keyspace
        conn = pycassa.system_manager.SystemManager(self.server_list()[0])
        try:
            conn.create_keyspace('test', pycassa.SIMPLE_STRATEGY, {'replication_factor': '1'})
        except pycassa.InvalidRequestException:
            pass
        conn.close()


class CassandraSkipIfNotInstalledDecorator(SkipIfNotInstalledDecorator):
    name = 'Cassandra'

    def search_server(self):
        find_cassandra_home()  # raise exception if not found


skipIfNotFound = skipIfNotInstalled = CassandraSkipIfNotInstalledDecorator()


def strip_version(dir):
    m = re.search('(\d+)\.(\d+)\.(\d+)', dir)
    if m is None:
        return None
    else:
        return tuple([int(ver) for ver in m.groups()])


def find_cassandra_home():
    cassandra_home = os.environ.get('CASSANDRA_HOME')
    if cassandra_home and os.path.exists(os.path.join(cassandra_home, 'bin', 'cassandra')):
        return cassandra_home

    for dir in SEARCH_PATHS:
        if os.path.exists(os.path.join(dir, 'bin', 'cassandra')):
            return dir

    # search newest cassandra-x.x.x directory
    cassandra_dirs = [dir for dir in glob("/usr/local/*cassandra*") if os.path.isdir(dir)]
    if cassandra_dirs:
        return sorted(cassandra_dirs, key=strip_version)[-1]

    raise RuntimeError("could not find CASSANDRA_HOME")

#!/usr/bin/env python
# -*- coding: utf-8 -*-

import functools
import json
import logging
import time

import motor.motor_tornado
import tornado
import tornado.httpclient
import tornado.web


###############################################################################
# Settings
###############################################################################

DEBUG = True

PORT = 8080

URL = 'https://vast-eyrie-4711.herokuapp.com/?key=%s'
FROM_CACHE = '/from_cache'

# cache expires in 24 hours
CACHE_TIMEOUT = 60 * 60 * 24

# If the fetching request is failed somehow
# then those requests which are waiting for the result
# from the cache will never get it.
# Delete the key to reset them (to make one of them fetching).
# fetching request expires in 5 minutes
FETCH_TIMEOUT = 5 * 60

MONGODB = 'mongodb://192.168.2.128:27017'

REQUEST_TIMEOUT = 10
DB_REQUEST_DELAY = 20

###############################################################################


logging.basicConfig(level=logging.DEBUG if DEBUG else logging.INFO)
(KEY, CONTENT, TIMESTAMP) = ("key", "content", "timestamp")


def expired(timestamp, timeout=CACHE_TIMEOUT):
    return time.time() - timestamp > timeout


class FromCacheHandler(tornado.web.RequestHandler):
    def initialize(self):
        self.aborted = False
        self.fetching = False
        self.key = None
        self.db = self.settings['db']
        self.http = tornado.httpclient.AsyncHTTPClient()
        self.ioloop = tornado.ioloop.IOLoop.current()

    def on_connection_close(self):
        self.aborted = True

    @tornado.web.asynchronous
    def get(self):
        qcs = dict(qc.split('=') for qc in self.request.query.split('&'))
        self.key = qcs.get('key')
        self.set_header('Content-Type', 'application/json')
        self.do_fetch()

    def do_fetch(self):
        logging.debug('Request to db.cache to find key=%s', self.key)
        cached = self.db.cache.find_one({KEY: self.key})
        cached.add_done_callback(self.call_fetch)

    def validate_cache(self):
        if not self.cache:
            return

        logging.debug('Validating: %s', self.cache)

        timestamp = self.cache[TIMESTAMP]
        if CONTENT not in self.cache and expired(timestamp, FETCH_TIMEOUT) \
                or expired(timestamp):
            logging.info('Expired %s, removing...', self.cache)
            self.db.cache.remove({KEY: self.key})
            self.cache = None
            self.fetching = False

    def still_alive(slf):
        def still_alive(method):
            @functools.wraps(method)
            def decorated(*args, **kwargs):
                if slf.aborted and not slf.fetching:
                    logging.warning('Aborted')
                    return
                return method(*args, **kwargs)
            return decorated
        return still_alive

    def call_fetch(self, resp):
        self.cache = resp.result()
        still_alive = self.still_alive()

        @still_alive
        def _do_request():
            self.validate_cache()

            if self.cache is None:
                now = time.time()
                ins = {KEY: self.key, TIMESTAMP: now}
                logging.info('Inserting: %s', ins)
                self.cache = ins
                self.db.cache.insert(ins, callback=http_fetch)
                return

            if CONTENT in self.cache:
                send(self.cache[CONTENT])
            else:
                self.ioloop.add_timeout(time.time() + DB_REQUEST_DELAY,
                                        self.do_fetch)

        def http_fetch(result, error):
            if error and not self.fetching:
                # duplicating request, just ignore it
                logging.info('Ignoring duplicating request...')
                return
            if not self.fetching:
                logging.debug('Mark request as fetching...')
            logging.info('Fetching...')
            self.fetching = True
            http_future = self.http.fetch(URL % self.key, raise_error=False)
            http_future.add_done_callback(handle_future)

        @still_alive
        def handle_future(resp):
            exception = resp.exception()
            if exception:
                return self.ioloop.call_later(1, lambda: _do_request())
            handle_response(resp.result())

        @still_alive
        def handle_response(result):
            if result.error:
                return self.ioloop.call_later(1, lambda: _do_request())

            upd = {CONTENT: result.body, TIMESTAMP: time.time()}
            logging.info('Update key=%s with: %s', self.key, upd)
            self.db.cache.update({KEY: self.key}, {"$set": upd}, upsert=True)
            self.cache.update(upd)
            send(result.body)

        @still_alive
        def send(body):
            logging.info('Result: %s', body)
            data = tornado.escape.json_decode(body)
            self.write(json.dumps(data))
            self.finish()

        _do_request()


def make_app():
    settings = {
        'xsrf_cookies': True,
        'cookie_secret': "__TODO:_GENERATE_YOUR_OWN_RANDOM_VALUE_HERE__",
        'debug': DEBUG,
        'db': motor.motor_tornado.MotorClient(MONGODB).cache,
    }
    settings['db'].cache.create_index("key", unique=True)

    return tornado.web.Application([
        (r"/from_cache/?", FromCacheHandler),
    ], **settings)


def run():
    application = make_app()
    application.listen(PORT)
    try:
        tornado.ioloop.IOLoop.current().start()
    except KeyboardInterrupt:
        tornado.ioloop.IOLoop.current().stop()


if __name__ == "__main__":
    run()

