def valid_check(request):
    if request.GET:
        dict = request.GET
        for key, value in dict.iteritems():
            if key == "username":
                try:
                    user = User.objects.get(username=value)
                except User.DoesNotExist:
                    user = None
            elif key == "email":
                try:
                    user = User.objects.get(email=value)
                except User.DoesNotExist:
                    user = None

            if user:
                return HttpResponse('invalid')
            else:
                return HttpResponse('valid')

    else:
        return HttpResponse('invalid')

